        for j in range(1, m):
            left, up, diag= arr[i][j-1], arr[i-1][j], arr[i-1][j-1]
            if board[i][j] == 1:
                if left==up==diag:
                    arr[i][j]= left+1
                else:
                    arr[i][j]= min(left, up, diag)+1
            else:
                arr[i][j]= 0

    maxEdge= max(max(arr[i]) for i in range(len(arr)))
    return maxEdge**2

